    add(task) { queue.push(task) },
    remaining() { return queue.length },
    run(now) {
      let spent = 0
      let executed = 0
      while (queue.length > 0) {
        const task = queue[0]
        queue.shift()
        spent += task()
        executed++
        if (spent >= budget) break
      }
      return { done: queue.length === 0, executed, spent, at: now }
    }
  }
