function evalConditional(type, opts) {
  const members = typeof type === 'object' && type.k === 'union' ? type.of : [type]
  const out = []
  for (const m of members) {
    out.push(isAssignable(m, opts.check).ok ? opts.then : opts.else)
  }
  return unionOf(out)
